import math,functools
from studio_lib.mesh import ease
from studio_lib.narration_timing import progress
from studio_lib.solid_parts import background as gradient
from studio_lib import parts_rich as P
FLOOR=.30

def state(t,tl):
    b=tl['beats']
    i=min(7,next((j for j,x in enumerate(b) if t<x['end']),7))
    cut=ease(progress(t,b[1]))*(1-ease(progress(t,b[7])))
    pull=ease(progress(t,b[2]))*0.6
    release=ease(progress(t,b[4]))*0.4
    cage_shift=pull-release
    return dict(beat=i,cut=cut,cage_shift=cage_shift)

@functools.lru_cache(maxsize=1)
def background():
    return gradient((15,27,39),(41,60,74))

def draw(s,t,tl,hidden=()):
    p=state(t,tl)
    # body
    if 'body' not in hidden:
        P.chamfer_box(s,(0,0,2.5),(4.0,0.2,0.5),(80,90,100),bevel=0.04)
    # anchor (fixed to frame)
    if 'anchor' not in hidden:
        P.plate(s,(-1.6,0,2.5),(0.2,0.6,0.5),(60,70,80),tiles=(4,2))
    # guide rail
    if 'guide' not in hidden:
        P.plate(s,(-0.8,0,2.5),(0.1,0.6,0.5),(100,110,120),tiles=(2,4))
    # spring (tension)
    if 'spring' not in hidden:
        P.spring(s,(-0.75,0.1,2.5),(-0.75,0.4,2.5),5,0.03,0.008,(180,190,200),steps=12)
    # cage (moves sideways)
    if 'cage' not in hidden:
        shift=p['cage_shift']*0.8
        P.chamfer_box(s,(shift,0,2.5),(0.6,0.1,0.4),(150,160,170),bevel=0.03)
    # upper pulley (driven)
    if 'pulley' not in hidden:
        angle=p['cage_shift']*2*math.pi
        P.gear(s,(0.2,0,2.6),0.25,12,angle,0.05,(220,180,140),tip=0.08,root=0.12,hub=0.08,holes=3,hole_r=0.02,mark=False)
    # lower pulley (idler)
    if 'link' not in hidden:
        P.gear(s,(0.2,0,2.3),0.22,10,0.0,0.04,(200,150,130),tip=0.07,root=0.11,hub=0.07,holes=2,hole_r=0.015,mark=False)
    # cover (cutaway)
    if 'cover' not in hidden and p['cut']<0.99:
        P.plate(s,(-0.2,0.3+0.6*p['cut'],2.5),(1.0,0.05,0.6),(90,100,110),tiles=(6,2))
    return p

SHOTS=[((0,0,2.5),1.4,.30),((0,0,2.5),1.6,.30),((0.2,0,2.5),1.8,.30),((-0.2,0,2.5),1.7,.30),((0,0,2.5),1.5,.30),((0,0,2.5),1.6,.30),((0,0,2.5),1.5,.30),((0,0,2.5),1.4,.30)]

def shot(i):
    return SHOTS[min(i,7)]

def elevation(t,tl):
    return 6.0
